// 용어 설명 자료 영어판(TERM_GLOSSARY_EN) — term_glossary.jsx 의 TERM_GLOSSARY_KO 와 같은 key·같은 모양. React 없음(데이터만).
// 항목마다 term·def 는 늘 두고, unit·ref 는 한국어 값에 한글이 있을 때만 둔다(없으면 한국어 값을 그대로 쓴다, langMerge).
// 화면이 읽는 TERM_GLOSSARY·TERM_HINT_LABELS 는 여기서 langPick 으로 만든다. index.html 에서 term_glossary.jsx 바로 뒤에 둔다.

const TERM_HINT_LABELS_EN = {
  button: (term) => `What is ${term}?`,
  unit: "Unit",
  ref: "Source",
  more: "Open in the glossary",
};

const TERM_GLOSSARY_EN = {
  // ── Concentration & exposure ──
  ppm: { term: "ppm (by volume)", def: "Volume of a gas or vapor per million volumes of air. Used only for gases and vapors." },
  mgm3: { term: "mg/m³", def: "Mass of substance per cubic metre of air. Dusts, fumes and mists are expressed only in this unit." },
  molar_mass: { term: "Molecular weight (molar mass)", def: "Mass of one mole of the substance. Use the molecular weight given in SDS Section 9." },
  molar_volume: { term: "Molar volume Vm", def: "Volume occupied by one mole of gas. For an ideal gas it is R·T/P, about 24.45 L at 25 °C and 1 atm." },
  oel: { term: "Occupational exposure limit (TLV/PEL)", def: "Airborne concentration to which nearly all workers may be exposed day after day without adverse health effects. Korea uses the MOEL exposure limits.", ref: "MOEL Notice: Exposure Limits for Chemical Substances and Physical Agents (Korea)" },
  twa: { term: "Time-weighted average (TWA)", def: "Exposure concentration averaged over an 8-hour workday, weighted by time: the sum of concentration × time for each period, divided by 8." },
  brief_scala: { term: "Brief & Scala adjustment", def: "Factor that lowers the exposure limit for shifts longer than 8 h, reflecting longer exposure and shorter recovery. RF = (8/h)·(24−h)/16." },
  exposure_index: { term: "Exposure index E", def: "For combined exposure, the sum of measured concentration ÷ exposure limit for each component. A value above 1 exceeds the mixture limit.", ref: "ACGIH TLV for mixtures, OSHA 1910.1000(d)(2)" },
  additive_effect: { term: "Additive effect", def: "When several substances act on the same organ by the same mechanism, their effects add. Only then are they summed in the exposure index." },
  generation_rate: { term: "Vapor generation rate", def: "Mass flow rate of vapor newly released into the workroom air. Equals the amount of liquid evaporated." },
  ventilation_rate: { term: "Ventilation rate", def: "Volumetric flow rate of air supplied to and exhausted from the room." },
  mixing_factor: { term: "Mixing factor K", def: "Safety factor for incomplete mixing of room air. K = 1 is perfect mixing; values of 3–10 are typical." },
  ach: { term: "Air changes per hour (ACH)", def: "Number of times the room air is replaced in one hour: ventilation rate × 60 ÷ room volume.", unit: "1/h (air changes)" },

  // ── Fire & explosion ──
  lfl: { term: "Lower flammable limit (LFL/LEL)", def: "Lowest concentration of a flammable gas or vapor in air that can be ignited. Below it, a flame will not propagate.", ref: "SDS Section 9" },
  ufl: { term: "Upper flammable limit (UFL/UEL)", def: "Highest concentration that can be ignited. Richer mixtures lack oxygen to burn, but enter the flammable range when diluted with air." },
  le_chatelier: { term: "Le Chatelier's rule", def: "Estimates the flammable limits of a mixture of flammable components from the pure-component limits: 1/LFL = Σ yᵢ/LFLᵢ." },
  stoich_o2: { term: "Stoichiometric oxygen z", def: "Moles of oxygen needed to burn one mole of fuel completely. For CₘHₓO_y it is m + x/4 − y/2." },
  stoich_air: { term: "Theoretical air", def: "Amount of air just sufficient for complete combustion: the required oxygen divided by the oxygen fraction of air (0.2095).", unit: "mol air/mol fuel" },
  afr: { term: "Air–fuel ratio (AFR)", def: "Mass of air per mass of fuel. Above the stoichiometric ratio the mixture is fuel-lean, with air left over." },
  excess_air: { term: "Excess air", def: "Air supplied beyond the theoretical amount, as a percentage. 20 % means 1.2 times the theoretical air." },
  cst: { term: "Stoichiometric concentration Cst", def: "Volume concentration of fuel in a fuel–air mixture whose proportions allow exactly complete combustion.", ref: "Crowl & Louvar, Ch. 6" },
  loc: { term: "Limiting oxygen concentration (LOC)", def: "Oxygen concentration below which a flame cannot propagate at any fuel concentration. Inerting below it prevents combustion.", ref: "Crowl & Louvar, Ch. 6" },

  composition_basis: { term: "Composition basis", def: "Whether the mixture composition is entered as mole fractions or mass fractions. Mass fractions are converted with the molar masses." },
  liaw_rule: { term: "Liaw mixture flash point rule", def: "Le Chatelier's rule combined with vapor–liquid equilibrium: the mixture flash point is the T where Σ xᵢγᵢPᵢ(T)/Pᵢ(T_fp,i) = 1.", ref: "Liaw et al. (2002)" },
  liquid_mole_fraction: { term: "Liquid mole fraction xᵢ", def: "Moles of component i divided by the total moles of the liquid mixture. All components add up to 1." },
  pure_flash_point: { term: "Pure-component flash point", def: "The (closed-cup) flash point of the component on its own. Its saturation vapor pressure there is roughly at the LFL.", ref: "SDS Section 9" },
  mix_flash_point: { term: "Mixture flash point", def: "Lowest liquid temperature at which the vapor over a liquid mixture ignites momentarily. Estimated from component flash points, composition and vapor pressures." },
  ghs_flam_liquid: { term: "GHS flammable liquid category", def: "GHS class set by flash point and initial boiling point: below 23 °C Category 1 or 2, 23–60 °C Category 3, 60–93 °C Category 4.", ref: "UN GHS Rev. 10, Table 2.6.1" },
  fuel_formula: { term: "Fuel formula CₘHₓO_y", def: "Numbers of carbon, hydrogen and oxygen atoms in the fuel molecule. They set the oxygen for complete combustion, z = m + x/4 − y/2." },
  inert_margin: { term: "Inerting safety margin", def: "Gap kept between the LOC and the controlled oxygen level. Practice is often to control 2–4 percentage points below the LOC.", ref: "Kinsley (2001)" },
  o2_setpoint: { term: "O₂ control target", def: "Oxygen level an inerted vessel must not exceed, set as the LOC minus a safety margin." },
  inert_dilution: { term: "Nitrogen dilution", def: "Nitrogen added to air to bring oxygen down to the target: 20.95/target − 1 mol per mol of air." },
  osfc: { term: "OSFC (out-of-service fuel concentration)", def: "Highest fuel concentration, when purging fuel out with N₂, at which later admitting air never enters the flammable zone.", ref: "Mashuga & Crowl (1998)" },
  isoc: { term: "ISOC (in-service oxygen concentration)", def: "Highest oxygen concentration, when purging air out with N₂, at which later admitting fuel never enters the flammable zone.", ref: "Mashuga & Crowl (1998)" },
  purge_method: { term: "Purge method", def: "Vacuum purge: evacuate, refill with N₂. Pressure purge: pressurize with N₂, vent. Sweep purge: N₂ in at one opening, out at another.", ref: "Crowl & Louvar, Ch. 7" },
  purge_volume: { term: "Purged volume", def: "Vapor-space volume of the vessel to be replaced with nitrogen, excluding any liquid." },
  o2_concentration: { term: "Oxygen concentration", def: "Volume (mole) fraction of oxygen in a gas mixture. Dry air is 20.95 vol%." },
  sweep_mixing_k: { term: "Mixing efficiency K (sweep)", def: "Factor correcting a sweep purge for incomplete mixing of the incoming nitrogen. 1 means perfect mixing.", ref: "Kinsley (2001)" },
  purge_flow: { term: "Purge nitrogen flow", def: "Volumetric flow of nitrogen into the vessel in a sweep purge. The required volume divided by it gives the purge time." },
  purge_cycles: { term: "Purge cycles", def: "One evacuate–refill or pressurize–vent pair counts as one cycle. Each cycle multiplies the oxygen by P_L/P_H." },
  n2_consumption: { term: "Nitrogen consumption", def: "Nitrogen used by the purge. A vacuum or pressure purge uses (P_H − P_L)V/RT mol per cycle." },
  normal_volume: { term: "Normal volume Nm³", def: "Gas volume converted to 0 °C and 1 atm. One kmol of nitrogen is about 22.4 Nm³." },
  dielectric_constant: { term: "Relative permittivity εr", def: "Permittivity of a material divided by that of vacuum. About 2 for hydrocarbons and about 80 for water." },
  liquid_conductivity: { term: "Liquid conductivity κ", def: "How readily a liquid conducts current. The lower it is, the longer charge from flow, filtering or mixing remains." },
  capacitance: { term: "Capacitance C", def: "Charge a conductor holds per volt of potential. A human body is about 100–200 pF; a drum tens to hundreds of pF." },
  static_voltage: { term: "Charged potential", def: "Voltage of an electrostatically charged conductor relative to earth. A walking person can reach several kV or more." },
  mie_ref: { term: "Reference MIE", def: "Minimum ignition energy of the flammable mixture the spark energy is compared with, measured at the most easily ignited concentration." },
  relaxation_time: { term: "Charge relaxation time τ", def: "Time for charge in a liquid to fall to 1/e (about 37 %) of its initial value. τ = ε₀εr/κ; about 0.7 % remains after 5τ." },
  conductivity_class: { term: "Conductivity class", def: "Liquids grouped by conductivity: below 50 pS/m low, 50–10,000 pS/m medium, above that high.", ref: "IEC TS 60079-32-1; NFPA 77 (values)" },
  stored_charge: { term: "Stored charge Q", def: "Charge held on a charged conductor: Q = C·V." },
  spark_energy: { term: "Spark energy W", def: "Maximum energy a charged conductor can release in one spark, ½CV². At or above the MIE it can ignite the mixture." },

  // ── Release, dispersion & relief ──
  evaporation_rate: { term: "Evaporation rate", def: "Mass of liquid converted to vapor at the liquid surface per unit time." },
  mass_transfer_coeff: { term: "Mass transfer coefficient K", def: "Coefficient giving how fast vapor moves from a liquid surface into air. Scaled from water (0.83 cm/s) by molecular weight.", ref: "Crowl & Louvar, Eq. 3-14" },
  emission_rate: { term: "Emission rate", def: "Mass flow rate of material continuously released from the source into the air." },
  wind_speed: { term: "Wind speed", def: "Mean wind speed at the release height (usually 10 m above ground). Higher speed gives more dilution." },
  stability_class: { term: "Atmospheric stability (Pasquill–Gifford)", def: "Classes from A (very unstable, strong mixing) to F (stable, weak vertical mixing), chosen from wind speed, insolation and cloud cover." },
  dispersion_sigma: { term: "Dispersion coefficients σy, σz", def: "Crosswind and vertical spread (standard deviations) of the plume concentration profile, set by downwind distance and stability class." },
  effective_height: { term: "Effective release height H", def: "Release height plus plume rise. Zero for a ground-level release." },
  relief_rate: { term: "Required relieving rate", def: "Flow the relief valve must discharge for an overpressure cause (fire, blocked outlet, control failure, etc.), set per scenario by API 521." },
  relieving_pressure: { term: "Relieving pressure P₁", def: "Absolute inlet pressure with the valve fully open: set pressure plus allowable overpressure (usually 10 %) plus atmospheric pressure.", unit: "kPa (abs)" },
  back_pressure: { term: "Back pressure P₂", def: "Absolute pressure at the valve outlet. Atmospheric for discharge to air; higher when tied into a flare system.", unit: "kPa (abs)" },
  kd: { term: "Effective discharge coefficient K_d", def: "Ratio of actual to ideal nozzle flow. For preliminary sizing use 0.975 for gas and 0.65 for liquid." },
  kb: { term: "Back-pressure correction factor K_b", def: "Corrects gas/vapor relief capacity for the reduction caused by back pressure. Equal to 1 when back pressure is low." },
  kc: { term: "Rupture disk combination factor K_c", def: "Capacity correction when a rupture disk is installed upstream of the relief valve: 1 without a disk, 0.9 with one." },
  kw: { term: "Back-pressure correction factor K_w", def: "Corrects for back pressure on balanced-bellows valves in liquid service. Equal to 1 for conventional valves." },
  kv: { term: "Viscosity correction factor K_v", def: "Corrects for reduced relief capacity with viscous liquids. Equal to 1 for thin liquids such as water." },
  heat_capacity_ratio: { term: "Heat capacity ratio k (= cp/cv)", def: "Constant-pressure heat capacity divided by constant-volume heat capacity. About 1.40 for air and 1.31 for methane; it sets the critical flow condition." },
  critical_flow: { term: "Critical (choked) flow", def: "State in which lowering the outlet pressure no longer increases flow. Occurs when back pressure ÷ relieving pressure is at or below the critical pressure ratio." },
  orifice_area: { term: "Effective orifice area", def: "Calculated valve nozzle area needed to pass the relieving rate. The selected valve's area must be equal or larger." },
  api526: { term: "API 526 orifice letter", def: "Standard letter designations for relief valve nozzle sizes, from D (0.110 in²) to T (26.0 in²)." },
  specific_gravity: { term: "Specific gravity G", def: "Ratio of the liquid's mass to that of an equal volume of water at standard conditions." },

  // ── Chemistry & thermodynamics ──
  ideal_gas: { term: "Ideal gas law", def: "Equation of state PV = nRT, neglecting molecular size and intermolecular forces. Accurate for gases near ambient conditions." },
  absolute_pressure: { term: "Absolute pressure", def: "Pressure measured from perfect vacuum: gauge pressure plus atmospheric pressure. Equations of state and vapor pressure use absolute pressure." },
  absolute_temperature: { term: "Absolute temperature", def: "Temperature measured from absolute zero (−273.15 °C), in kelvin. Equations of state use absolute temperature." },
  mol: { term: "Amount of substance n", def: "Quantity of substance counted in particles. One mole is 6.022 × 10²³ particles." },
  compressibility: { term: "Compressibility factor Z", def: "PV of a real gas divided by nRT at the same conditions. Z = 1 for an ideal gas; the farther from 1, the stronger the non-ideal behavior." },
  critical_point: { term: "Critical point (T_c, P_c)", def: "Temperature and pressure at which liquid and vapor become indistinguishable. Above T_c a gas cannot be liquefied by pressure alone." },
  reduced_property: { term: "Reduced temperature and pressure", def: "Temperature and pressure divided by their critical values (T/T_c, P/P_c). Fluids at equal reduced conditions behave alike (corresponding states)." },
  acentric_factor: { term: "Acentric factor ω", def: "Measure, based on vapor pressure, of how far a molecule departs from spherical symmetry. Near zero for monatomic gases such as argon." },
  dilution: { term: "Dilution (C₁V₁ = C₂V₂)", def: "Adding solvent does not change the amount of solute, so stock concentration × stock volume = final concentration × final volume." },
  molarity: { term: "Molarity M", def: "Moles of solute per litre of solution. Changes slightly with temperature as the volume changes." },
  mass_percent: { term: "Mass percent (w/w %)", def: "Mass of solute as a percentage of the total solution mass." },
  molality: { term: "Molality b", def: "Moles of solute per kilogram of solvent. Being mass-based, it does not change with temperature." },
  density: { term: "Density ρ", def: "Mass per unit volume. Varies with temperature for liquids and with temperature and pressure for gases." },
  ph: { term: "pH", def: "Negative base-10 logarithm of hydrogen ion activity. At 25 °C, 7 is neutral and lower values are acidic." },
  pka: { term: "pKa", def: "Negative base-10 logarithm of the acid dissociation constant Ka. When pH = pKa, the acid and its conjugate base are present in equal amounts." },
  buffer: { term: "Buffer solution", def: "Solution of a weak acid and its conjugate base (or weak base and conjugate acid) that resists pH change. Most effective within pH = pKa ± 1." },
  antoine_constants: { term: "Antoine constants A, B, C", def: "Substance-specific constants fitted to data in log P = A − B/(C + T). Use only with the units and temperature range of the fit." },
  vapor_pressure: { term: "Vapor pressure (saturation pressure)", def: "Pressure of a vapor in equilibrium with its liquid. Rises with temperature; the liquid boils when it equals the surrounding pressure.", ref: "SDS Section 9" },
  boiling_point: { term: "Boiling point", def: "Temperature at which the vapor pressure equals the surrounding pressure. Lower pressure gives a lower boiling point." },
  saturation: { term: "Saturation (saturation pressure and temperature)", def: "State in which liquid and vapor coexist in equilibrium. For a pure substance, each saturation temperature fixes a single saturation pressure." },

  // ── Fluids & piping ──
  reynolds: { term: "Reynolds number Re", def: "Ratio of inertial to viscous forces (ρvD/μ). Low values mean laminar, high values turbulent flow; in round pipes the bounds are about 2100 and 4000." },
  flow_regime: { term: "Flow regime", def: "Laminar flow moves in smooth layers, turbulent flow has mixing eddies, and the range between them is the transition region." },
  mean_velocity: { term: "Mean velocity", def: "Volumetric flow rate divided by the pipe cross-sectional area." },
  viscosity: { term: "Viscosity μ", def: "A fluid's resistance to flow (dynamic, not kinematic, viscosity). Water at 20 °C is about 1.0 cP (mPa·s)." },
  roughness: { term: "Absolute roughness ε", def: "Mean height of irregularities on the inner pipe wall. About 0.046 mm for commercial steel; nearly zero for smooth glass or plastic." },
  friction_factor: { term: "Darcy friction factor f", def: "Dimensionless coefficient for pressure loss from wall friction, set by Re and relative roughness ε/D. Four times the Fanning factor." },
  pressure_drop: { term: "Pressure drop ΔP", def: "Pressure lost to friction and other losses as fluid flows through pipes and equipment." },
  head_loss: { term: "Head loss h_f", def: "Pressure drop expressed as a height of the flowing liquid column (ΔP/ρg)." },
  total_head: { term: "Total head H", def: "Energy the pump must add to the liquid, expressed as liquid column height: the sum of elevation difference, pressure difference and piping losses." },
  pump_efficiency: { term: "Pump efficiency η", def: "Fraction of the shaft power input that is delivered to the liquid." },
  hydraulic_power: { term: "Hydraulic power", def: "Power actually delivered to the liquid by the pump (ρgQH)." },
  shaft_power: { term: "Shaft (brake) power", def: "Power needed to drive the pump shaft: hydraulic power ÷ pump efficiency. Motor efficiency is not included." },
  npsha: { term: "NPSHa (net positive suction head available)", def: "Margin of liquid pressure above vapor pressure at the pump inlet, expressed as head. Set by the suction-side system." },
  npshr: { term: "NPSHr (net positive suction head required)", def: "Suction head the pump needs to avoid cavitation, read from the manufacturer's performance curve (NPSH3)." },
  static_head: { term: "Static suction head z_s", def: "Height of the suction liquid level relative to the pump centerline. Positive if above the pump, negative (suction lift) if below." },
  discharge_coefficient: { term: "Discharge coefficient C", def: "Ratio of actual to theoretical flow through an orifice. About 0.6 for a sharp-edged orifice." },
  beta_ratio: { term: "Diameter ratio β", def: "Orifice bore diameter divided by pipe inside diameter. ISO 5167-2 covers 0.1–0.75." },
  permanent_loss: { term: "Permanent pressure loss", def: "Pressure loss that remains after pressure recovery downstream of the orifice. It is smaller than the measured differential pressure." },
  design_velocity: { term: "Design velocity", def: "Target mean velocity used to size a pipe. Higher velocity gives a smaller pipe but more pressure drop, erosion and noise." },

  // ── Heat transfer & psychrometrics ──
  mass_flow: { term: "Mass flow rate ṁ", def: "Mass of fluid flowing per unit time." },
  cp: { term: "Specific heat cp", def: "Heat needed to raise 1 kg of a substance by 1 K at constant pressure. About 4.18 kJ/(kg·K) for water." },
  sensible_heat: { term: "Sensible heat", def: "Heat that changes temperature without a phase change. Heat of phase change at constant temperature, such as evaporation or condensation, is latent heat." },
  lmtd: { term: "Log mean temperature difference (LMTD)", def: "Logarithmic mean of the temperature differences at the two ends of a heat exchanger; the mean driving force for the whole exchanger.", ref: "Incropera, Ch. 11" },
  flow_arrangement: { term: "Counterflow / parallel flow", def: "Counterflow: the fluids flow in opposite directions; parallel flow: the same direction. For equal terminal temperatures, counterflow gives the larger LMTD." },
  overall_u: { term: "Overall heat transfer coefficient U", def: "Coefficient combining convection on both sides, wall conduction and fouling resistances. Heat duty is Q = U·A·ΔT." },
  heat_transfer_area: { term: "Heat transfer area A", def: "Wall area through which heat passes in the exchanger. Must match the reference surface for U (usually the tube outside surface)." },
  thermal_conductivity: { term: "Thermal conductivity k", def: "Ability of a material to conduct heat. Insulation 0.03–0.06, water about 0.6, steel about 50 W/(m·K)." },
  convection_coeff: { term: "Convection heat transfer coefficient h", def: "Heat transfer between a surface and a moving fluid. Gas free convection about 2–25; liquid forced convection about 100–20 000 W/(m²·K) (Incropera Table 1.1)." },
  critical_radius: { term: "Critical radius of insulation", def: "Outer radius (k/h) beyond which added insulation reduces heat loss. For pipes smaller than this, thin insulation increases heat loss.", ref: "Incropera, Sec. 3.3" },
  prandtl: { term: "Prandtl number Pr", def: "Ratio of momentum diffusivity to thermal diffusivity (cp·μ/k). About 0.7 for air and 7 for water." },
  nusselt: { term: "Nusselt number Nu", def: "Ratio of convective to conductive heat transfer across a fluid layer of the same thickness (hD/k)." },
  dry_bulb: { term: "Dry-bulb temperature", def: "Air temperature read by an ordinary thermometer, as distinct from the wet-bulb temperature read with a wetted wick." },
  relative_humidity: { term: "Relative humidity", def: "Partial pressure of water vapor in air divided by the saturation vapor pressure at the same temperature." },
  humidity_ratio: { term: "Humidity ratio W", def: "Mass of water vapor per kilogram of dry air. Stays constant with temperature changes as long as no moisture is added or removed." },
  dew_point: { term: "Dew point", def: "Temperature at which water vapor starts to condense when air is cooled at constant moisture content. Surfaces colder than this collect condensation." },
  moist_enthalpy: { term: "Moist air enthalpy", def: "Enthalpy of 1 kg of dry air plus its water vapor, relative to dry air and liquid water at 0 °C. Used in HVAC load calculations." },
  specific_volume: { term: "Specific volume", def: "Volume of moist air per kilogram of dry air. Used to convert volumetric airflow to mass flow." },
  vapor_partial_pressure: { term: "Water vapor partial pressure p_w", def: "Share of the total moist-air pressure exerted by water vapor. The temperature at which it equals the saturation pressure is the dew point." },
  psy_process: { term: "Psychrometric process", def: "A change of air state. Heating or cooling changes temperature across a coil (cooling below the dew point also dehumidifies); mixing combines two streams.", ref: "ASHRAE Fundamentals, Ch. 1" },
  air_volume_flow: { term: "Airflow", def: "Volumetric flow measured at that air state. Dividing by the specific volume gives the dry-air mass flow." },
  dry_air_flow: { term: "Dry-air mass flow", def: "Mass flow of the dry air alone. It stays constant when moisture is added or removed, so it is the basis for heating, cooling and mixing balances." },
  coil_load: { term: "Coil heat rate", def: "Heat the coil adds to or removes from the air. A cooling coil removes both sensible heat and the latent heat of condensation." },
  condensate: { term: "Condensate rate", def: "Water condensed out of the air in a cooling coil: dry-air mass flow × drop in humidity ratio." },

  // ── Steam tables (IAPWS-IF97) ──
  steam_state_pair: { term: "Two properties that fix the state", def: "Two independent properties fix the state of pure water. In wet steam, T and p are linked, so another property such as quality is needed." },
  if97_region: { term: "IF97 region", def: "IAPWS-IF97 zones: 1 compressed liquid, 2 superheated vapor, 3 near-critical, 4 saturation (wet steam), 5 high-temperature steam above 1073 K." },
  steam_phase: { term: "Phase of water", def: "Compressed liquid (below the boiling point), wet steam (liquid and vapor mixed), superheated vapor (above the boiling point), or supercritical fluid." },
  steam_quality: { term: "Quality x", def: "Mass fraction of vapor in 1 kg of wet steam. 0 is saturated liquid and 1 is saturated (dry) vapor." },
  specific_enthalpy: { term: "Specific enthalpy h", def: "Enthalpy per kilogram (internal energy + pressure × volume). Used for constant-pressure heating, turbine work and heat-exchanger duty." },
  specific_entropy: { term: "Specific entropy s", def: "Entropy per kilogram. It stays constant in an ideal (reversible adiabatic) expansion or compression, which is the basis of turbine and pump efficiency." },
  internal_energy: { term: "Specific internal energy u", def: "Energy per kilogram held in molecular motion and bonds: enthalpy minus pressure × specific volume (u = h − p v)." },
  water_specific_volume: { term: "Specific volume v (water/steam)", def: "Volume occupied by 1 kg; the reciprocal of density. For steam it grows sharply as pressure falls." },
  cv: { term: "Isochoric heat capacity cv", def: "Heat needed to raise 1 kg by 1 K at constant volume. Smaller than cp for gases and close to cp for liquids." },
  speed_of_sound: { term: "Speed of sound w", def: "Speed at which pressure waves travel through the fluid. It sets the upper limit of velocity in choked nozzle or pipe flow." },
  latent_heat: { term: "Latent heat of vaporization h_fg", def: "Heat to turn 1 kg of saturated liquid into saturated vapor at the same temperature (h_g − h_f). Shrinks with pressure and is zero at the critical point." },
  steam_chart: { term: "T–s diagram · Mollier (h–s) chart", def: "Diagram with entropy on the x-axis and temperature (T–s) or enthalpy (h–s, Mollier) on the y-axis, showing the saturation dome and states." },
  saturation_table: { term: "Saturated steam table", def: "Table listing, for each saturation temperature (or pressure), the specific volume, enthalpy and entropy of saturated liquid (f) and vapor (g)." },
  table_step: { term: "Table step", def: "Increment from one table row to the next. A smaller step gives more rows." },

  // ── Unit conversion (calc_units_converter.jsx) ──
  unit_conversion: { term: "Unit conversion (converter)", def: "Expressing the same quantity in another unit: multiply by the scale factor, and for temperature and gauge pressure also shift the zero point.", ref: "NIST SP 811, Appendix B" },
  gauge_pressure: { term: "Gauge pressure (g)", def: "Pressure measured from atmospheric pressure — what a pressure gauge reads, marked with g (barg, psig, kgf/cm²g). Absolute = gauge + atmospheric." },
  atmospheric_pressure: { term: "Atmospheric pressure", def: "Pressure of the air at the site. The sea-level standard is 101.325 kPa; it is lower at higher altitude." },
  normal_m3: { term: "Nm³ (normal cubic metre)", def: "Gas volume converted to 0 °C and 101.325 kPa. One kmol of ideal gas is 22.414 Nm³." },
  standard_m3: { term: "Sm³ (standard cubic metre)", def: "Gas volume converted to agreed standard conditions (often 15 °C, 101.325 kPa). The reference temperature varies by contract and country." },
  actual_m3: { term: "Am³ (actual cubic metre)", def: "Gas volume at the actual operating temperature and pressure. Piping and equipment are sized on this value." },
  standard_cubic_feet: { term: "SCF (standard cubic foot)", def: "Gas volume in ft³ converted to 60 °F and 14.696 psia. One lb-mol of ideal gas is 379.49 scf; MMSCFD is a million scf per day." },
  reference_conditions: { term: "Reference conditions", def: "Temperature and pressure that define a standard volume (Nm³, Sm³, SCF). The same amount of gas gives different volumes on different bases." },
  volumetric_flow: { term: "Volumetric flow rate", def: "Volume of fluid flowing per unit time. For gases it depends on temperature and pressure, so state the conditions." },
  molar_flow: { term: "Molar flow rate", def: "Moles of substance flowing per unit time: mass flow ÷ molar mass. Converts directly to a standard gas volume flow." },
  mass_quantity: { term: "Mass", def: "Amount of matter expressed by weight. The SI unit is kg; 1 lb = 0.453 592 37 kg exactly." },
  energy: { term: "Energy / heat", def: "Amount of work or heat. SI unit J; 1 kcal (IT) = 4.1868 kJ, 1 kWh = 3.6 MJ, 1 Btu (IT) = 1.055 kJ." },
  power: { term: "Power / heat rate", def: "Work done or heat transferred per unit time. SI unit W; 1 kcal/h = 1.163 W, 1 ton of refrigeration (RT) = 3.517 kW." },
  heat_flux: { term: "Heat flux", def: "Heat flow per unit area. Used for fire radiation and heat-exchanger area calculations." },
  kinematic_viscosity: { term: "Kinematic viscosity ν", def: "Viscosity divided by density, ν = μ/ρ. 1 cSt = 1 mm²/s; water at 20 °C is about 1 cSt." },
  heat_transfer_coeff: { term: "Heat transfer coefficient", def: "Heat flow per m² of area per kelvin of temperature difference. The film coefficient h and the overall coefficient U use the same unit." },

  // ── Vessels & reactors ──
  vessel_head: { term: "Vessel head", def: "End closure of a cylindrical vessel: hemispherical, 2:1 elliptical, torispherical (crown and knuckle) or flat, each with its own depth and volume." },
  tangent_line: { term: "Tangent line", def: "Line where the cylindrical shell meets the curved head. Shell length is measured between the two tangent lines." },
  liquid_level: { term: "Liquid level", def: "Height from the vessel bottom to the liquid surface: from the shell bottom for horizontal vessels, from the lowest point of the bottom head for vertical ones." },
  reactor_type: { term: "CSTR / PFR", def: "A CSTR is a well-mixed tank whose contents match the outlet composition; a PFR is a tube in which fluid moves as a plug without axial mixing.", ref: "Fogler, Ch. 2" },
  rate_constant: { term: "Rate constant k", def: "Proportionality constant in the first-order rate law −r_A = k·C_A. Increases with temperature according to the Arrhenius equation." },
  conversion: { term: "Conversion X", def: "Fraction of the reactant fed that has reacted." },
  residence_time: { term: "Space time τ", def: "Reactor volume divided by inlet volumetric flow rate. Equals the mean residence time for constant-density (liquid) systems." },
  damkohler: { term: "Damköhler number", def: "Ratio of reaction rate to convective (flow) rate. For a first-order reaction it is k·τ; larger values give higher conversion." },

  // ── Reaction, runaway, economics & flue gas ──
  rx_order: { term: "Reaction order n", def: "Concentration exponent in the rate law −r_A = k·C_A^n. Found by experiment; for orders other than 1, the unit of k includes concentration.", ref: "Fogler, Ch. 3" },
  rx_half_life: { term: "Half-life t½", def: "Time for the reactant concentration to fall to half its initial value. For first order it is ln 2/k, independent of C_A0; other orders depend on C_A0." },
  rx_arrhenius_fit: { term: "Arrhenius fit", def: "Straight-line fit of ln k against 1/T from rate constants at several temperatures, giving the activation energy (slope −Ea/R) and pre-exponential factor A.", ref: "Fogler, Ch. 3" },
  rx_activation_energy: { term: "Activation energy Ea", def: "Measure of how strongly the rate constant depends on temperature (k = A·e^(−Ea/RT)). The larger it is, the faster the reaction speeds up as temperature rises." },
  rx_heat: { term: "Heat of reaction ΔH_rx", def: "Enthalpy change per mole of reactant reacted. Negative for exothermic reactions; in an adiabatic reactor it raises the temperature accordingly." },
  rx_sum_cp: { term: "Σ θᵢ·Cpᵢ", def: "Sum of molar heat capacities of all species fed (including inerts) per mole of limiting reactant A. θᵢ is inlet moles of i over inlet moles of A.", ref: "Fogler, Ch. 11" },
  rx_equilibrium_k: { term: "Equilibrium constant K, equilibrium conversion", def: "Constant fixing the composition at which a reversible reaction stops. For exothermic reactions, K and equilibrium conversion fall with temperature (van't Hoff).", ref: "Fogler, Ch. 11" },
  rx_dtad: { term: "Adiabatic temperature rise ΔTad", def: "Temperature rise when all the heat of reaction heats the reaction mass with no loss. ΔTad = Q′r/cp′ (mass basis) or (−ΔH)/ΣθCp." },
  rw_reaction_energy: { term: "Specific heat of reaction Q′r", def: "Heat released by the main reaction per kilogram of reaction mass. Measured by reaction calorimetry; the basis of the adiabatic temperature rise." },
  rw_accumulation: { term: "Accumulation X_ac", def: "Fraction of reactant still unreacted when cooling fails. For semi-batch it follows from feed and reaction rates; for batch it is 100 %." },
  rw_mtsr: { term: "MTSR (maximum temperature of the synthesis reaction)", def: "Temperature reached if the accumulated reactant reacts adiabatically after a cooling failure. MTSR = Tp + X_ac·ΔTad." },
  rw_mtt: { term: "MTT (maximum temperature for technical reasons)", def: "Equipment temperature limit: the boiling point (open systems) or the temperature at the maximum allowed pressure (closed systems). Boiling can act as a barrier." },
  rw_heat_release_rate: { term: "Specific heat release rate q", def: "Rate of heat release per kilogram at a given temperature. Measured by DSC or adiabatic calorimetry and shifted to other temperatures with the Arrhenius law." },
  rw_tmrad: { term: "TMRad (time to maximum rate, adiabatic)", def: "Time for a decomposition to reach its maximum rate once conditions become adiabatic. Zero-order approximation: cp·R·T²/(q·Ea)." },
  rw_td24: { term: "TD24", def: "Temperature at which TMRad is 24 h. If MTSR is below it, a decomposition runaway within a day of a cooling failure is considered unlikely." },
  rw_criticality: { term: "Stoessel criticality class", def: "Classification of a cooling-failure scenario into classes 1–5 by the order of Tp, MTSR, MTT and TD24. Higher classes are more critical and need more safeguards." },
  ec_capacity_exponent: { term: "Capacity exponent n (six-tenths rule)", def: "Exponent in the assumption that equipment cost scales with capacity to the power n. Economies of scale make it below 1; 0.6 is the usual average." },
  ec_cost_index: { term: "Cost index", def: "Index of the yearly price level of equipment and construction. An old estimate is moved to today by the ratio of two years' index values (e.g. CEPCI).", ref: "Turton, Ch. 7" },
  ec_ppi: { term: "Producer Price Index PPI (BLS)", def: "Producer price indexes by industry and product from the US Bureau of Labor Statistics. Public domain; used as a proxy for equipment price changes." },
  ec_discount_rate: { term: "Discount rate i", def: "Annual rate used to convert future money to present value, usually the company's cost of capital or target rate of return.", unit: "%/yr" },
  ec_npv: { term: "Net present value NPV", def: "Sum of all yearly cash flows converted to present value at the discount rate. Positive means the investment pays at that rate.", ref: "Turton, Ch. 10" },
  ec_irr: { term: "Internal rate of return IRR", def: "Discount rate at which NPV is zero. An IRR above the target rate suggests the investment is worthwhile; several may exist if cash-flow signs change repeatedly.", ref: "Turton, Ch. 10" },
  ec_payback: { term: "Payback period", def: "Time for the cumulative cash flow to reach zero, recovering the investment. Discounted payback uses discounted cash flows.", unit: "yr" },
  fg_dry_basis: { term: "Dry basis (flue gas)", def: "Concentration expressed on the flue gas with water vapor removed. Analyzers usually condense the water first, so they read dry-basis values." },
  fg_acid_dew_point: { term: "Sulfuric acid dew point", def: "Temperature at which SO₃ and water vapor start to condense as sulfuric acid. Far above the water dew point; cooling below it corrodes ducts and air heaters." },
  fg_stack_loss: { term: "Stack loss qA", def: "Fraction of fuel heat lost as sensible heat of the flue gas leaving the stack. Grows with flue gas temperature and excess air." },
  // ── Process control ──
  process_gain: { term: "Process gain K", def: "Final change in the controlled variable divided by the size of the step in the manipulated variable (controller output). K = Δy/Δu." },
  time_constant: { term: "Time constant τ", def: "Time for a first-order step response to reach 63.2 % of its final change, counted after the dead time. Larger means a slower process.", ref: "Seborg, Ch. 5" },
  dead_time: { term: "Dead time θ", def: "Pure delay between an input change and the first output movement, e.g. from pipe transport or analyser lag. Control gets harder as θ/τ grows." },
  two_point_fit: { term: "Two-point fit (Smith method)", def: "Fits a first-order-plus-dead-time model from the times a step response reaches 28.3 % and 63.2 %: τ = 1.5(t₆₃ − t₂₈), θ = t₆₃ − τ.", ref: "Smith & Corripio, Ch. 7" },
  pid_controller: { term: "PID controller", def: "Sets the manipulated variable from proportional (P), integral (I) and derivative (D) terms of the error. Ideal form: u = Kc(e + ∫e dt/τI + τD de/dt)." },
  closed_loop_tc: { term: "Closed-loop time constant τc (λ)", def: "Design value in IMC and SIMC tuning that sets the desired closed-loop speed. Smaller is faster but less robust; Skogestad recommends τc = θ." },
  ultimate_gain: { term: "Ultimate gain Ku", def: "Controller gain at which a P-only loop oscillates with constant amplitude (stability limit). Input to the Ziegler–Nichols ultimate gain method." },
  ultimate_period: { term: "Ultimate period Pu", def: "Period of the sustained oscillation at the ultimate gain Ku. Pu = 2π/ω_u." },
  tuning_rules: { term: "PID tuning rules", def: "Formulas giving Kc, τI and τD directly from a process model (K, τ, θ) or test data. Results differ with the goal: quarter decay, least error or a set speed." },
  ziegler_nichols: { term: "Ziegler–Nichols method", def: "1942 tuning method with a reaction-curve (step test) and an ultimate-gain (continuous cycling) version. It aims at quarter decay, so responses oscillate." },
  setpoint: { term: "Setpoint (SP)", def: "Target value for the controlled variable. A setpoint step response shows tracking performance." },
  disturbance: { term: "Disturbance (load)", def: "Input that affects the controlled variable but cannot be manipulated by the controller. A load step response shows disturbance rejection." },
  proportional_action: { term: "Proportional gain Kc", def: "Change in controller output per unit of error. Higher is faster but more oscillatory; P-only control leaves an offset." },
  integral_action: { term: "Integral time τI", def: "Time for integral action to repeat the proportional action. It removes offset; a smaller τI means stronger integral action." },
  derivative_action: { term: "Derivative time τD", def: "Multiplies the rate of change of the error. It anticipates and damps oscillation but amplifies measurement noise, so it is used with a filter." },
  iae: { term: "IAE (integral of absolute error)", def: "Time integral of the absolute error. Smaller means the loop follows the setpoint faster and more accurately.", ref: "Seborg, Eq. 12-35" },
  transfer_function: { term: "Transfer function", def: "Ratio of the Laplace transforms of output and input of a linear system (deviation variables). First order K/(τs+1); second order K/(τ²s²+2ζτs+1)." },
  second_order_system: { term: "Second-order system", def: "Process whose transfer-function denominator is quadratic in s. With damping ratio ζ < 1 it oscillates while settling." },
  bode_plot: { term: "Bode plot", def: "Plot of amplitude ratio (log scale) and phase angle against frequency ω. Gain and phase margins and crossover frequencies are read from it." },
  damping_coefficient: { term: "Damping ratio ζ", def: "Sets how oscillatory a second-order system is: ζ < 1 underdamped (oscillates), ζ = 1 critically damped, ζ > 1 overdamped." },
  control_overshoot: { term: "Overshoot", def: "Maximum amount by which the response exceeds its final value, divided by the final change. For a second-order system it is exp(−πζ/√(1−ζ²))." },
  decay_ratio: { term: "Decay ratio", def: "Ratio of the overshoots of two successive peaks. For a second-order system it is the overshoot squared; ZN tuning targets 1/4." },
  oscillation_period: { term: "Period of oscillation P", def: "Time between two successive peaks of an underdamped response. For a second-order system it is 2πτ/√(1−ζ²)." },
  rise_time_settling_time: { term: "Rise time and settling time", def: "Rise time is when the response first reaches its final value; settling time is when it stays within ±5 % (or ±2 %) of it." },
  routh_hurwitz: { term: "Routh–Hurwitz criterion", def: "Counts right-half-plane roots without solving for them, from sign changes in the first column of the Routh array of the characteristic equation." },
  rhp_roots: { term: "Right-half-plane roots", def: "Roots of the characteristic equation with a positive real part. Any such root makes the system unstable: its response grows with time." },
  crossover_freq: { term: "Crossover frequency", def: "Gain crossover is where the open-loop amplitude ratio is 1; phase crossover is where the phase is −180°. At the P-control limit ω_u = 2π/Pu." },
  gain_margin: { term: "Gain margin GM", def: "Inverse of the amplitude ratio at the −180° phase frequency: the factor loop gain can grow by before instability. Usually 1.7–2 or more." },
  phase_margin: { term: "Phase margin PM", def: "Angle by which the phase exceeds −180° at the frequency where the amplitude ratio is 1. Usually 30–45° or more." },

  // ── Separations (distillation, absorption) ──
  mole_fraction: { term: "Mole fraction", def: "Share of a component in the total moles of a mixture: x for liquid, y for vapour, z for feed. The fractions of all components add up to 1." },
  k_value: { term: "K-value (VLE ratio)", def: "Vapour mole fraction ÷ liquid mole fraction at equilibrium (K = y/x). Above 1 the component favours the vapour. Under Raoult's law K = Psat/P." },
  bubble_point: { term: "Bubble & dew point", def: "Bubble point: where heated liquid forms its first bubble. Dew point: where cooled vapour forms its first drop. Between them vapour and liquid coexist." },
  flash_vle: { term: "Isothermal flash", def: "Equilibrium split of a feed into vapour and liquid at a set T and P. The Rachford–Rice equation gives the vapour fraction and both compositions.", ref: "Rachford & Rice (1952)" },
  vapor_fraction: { term: "Vapour fraction V/F", def: "Share of the feed moles that leave a flash as vapour: 0 means all liquid, 1 means all vapour." },
  relative_volatility: { term: "Relative volatility α", def: "Ratio of two components' K-values (α = K_light/K_heavy). The larger it is, the easier the distillation; at 1 they cannot be separated (azeotrope)." },
  q_feed: { term: "Feed condition q", def: "Moles of liquid added at the feed stage per mole of feed: 1 for saturated liquid, 0 for saturated vapour, above 1 subcooled, below 0 superheated." },
  reflux_ratio: { term: "Reflux ratio R", def: "Liquid returned to the column L divided by distillate product D (R = L/D). Larger R means fewer stages and more energy." },
  min_reflux: { term: "Minimum reflux Rmin", def: "Smallest reflux ratio that achieves the split, needing infinite stages; set by the pinch on the equilibrium curve. Columns run at about 1.2–1.5 Rmin." },
  min_stages: { term: "Minimum stages Nmin", def: "Theoretical stages for the separation at total reflux (no product). With constant α the Fenske equation gives it directly.", ref: "Fenske (1932)" },
  theoretical_stage: { term: "Theoretical (equilibrium) stage", def: "An ideal stage whose leaving vapour and liquid are in equilibrium. Actual trays ≈ theoretical stages ÷ tray efficiency." },
  feed_stage: { term: "Feed stage", def: "The stage where feed enters. Feeding where the rectifying and stripping lines meet gives the fewest stages (optimal feed stage)." },
  cut_fraction: { term: "Distillate fraction D/F", def: "Share of the feed moles leaving as distillate (or as collected distillate in simple distillation)." },
  key_component: { term: "Key components LK, HK", def: "The two components that define a multicomponent split: the light key (LK) mostly goes overhead, the heavy key (HK) mostly to the bottoms, at set recoveries." },
  batch_charge: { term: "Still charge", def: "In simple (batch) distillation, moles of initial charge F, final residue W and collected distillate D, with F = W + D." },
  absorption_factor: { term: "Absorption factor A", def: "Operating-line slope ÷ equilibrium slope (A = L/mV). Above 1, adding stages can absorb almost all solute. The stripping factor is S = 1/A.", ref: "Kremser (1930)" },
  henry_slope: { term: "Equilibrium slope m", def: "Proportionality between vapour and liquid mole fractions in dilute solution (y* = m x): Henry's constant ÷ total pressure, or Psat/P." },
  liquid_gas_ratio: { term: "Liquid-to-gas ratio L/V", def: "Molar flow of solvent to gas in an absorber. It must exceed the minimum ratio and is usually set at 1.2–2 times it." },
  ntu: { term: "Number of transfer units NTU", def: "How many times the average driving force fits into the required concentration change in a packed column (NOG etc.). Packed height = HTU × NTU." },
  htu: { term: "Height of a transfer unit HTU", def: "Packed height per transfer unit (HOG = G/Kya): the molar flux divided by the overall capacity coefficient." },
  // ── Equipment sizing ──
  system_curve: { term: "System curve", def: "Head the piping system needs at each flow: static head plus friction and fitting losses (about ∝ Q²). It meets the pump curve at the operating point." },
  loss_coefficient: { term: "Loss coefficient K", def: "Pressure loss of a fitting, valve, entrance or exit as a multiple of the velocity head: ΔP = K·ρv²/2. The 2-K and 3-K methods make K a function of Re and size." },
  affinity_ratio: { term: "Affinity ratio s", def: "New/rated speed, or new/rated impeller diameter. By the affinity laws flow scales with s, head with s² and power with s³." },
  piping_geometry_factor: { term: "Piping geometry factor FP", def: "Factor (≤ 1) for the capacity lost when reducers or expanders are fitted at the valve. Found iteratively from the sum of loss coefficients and C/d²." },
  valve_fl: { term: "Liquid pressure recovery factor FL", def: "How much pressure recovers downstream of the valve's vena contracta. A lower FL means more recovery, so cavitation and choking start at a lower pressure drop." },
  valve_xt: { term: "Choked pressure-drop ratio factor xT", def: "Pressure-drop ratio x = Δp/P₁ at which gas flow through the valve chokes (air basis; Fγ corrects for k). Given by the vendor per valve style and opening." },
  valve_fd: { term: "Valve style modifier Fd", def: "Corrects the valve Reynolds number for the flow-path geometry. Used for the Reynolds factor FR with viscous fluids or small flows." },
  valve_ff: { term: "Liquid critical pressure ratio factor FF", def: "Ratio of the vena contracta pressure at choked flow to the vapour pressure: FF = 0.96 − 0.28·√(Pv/Pc)." },
  choked_flow_valve: { term: "Choked flow (valve)", def: "Condition in which a larger pressure drop no longer raises the flow: cavitation or flashing for liquids, sonic velocity at the throat for gases." },
  expansion_factor: { term: "Expansion factor Y", def: "Accounts for the density change as gas expands through the valve: Y = 1 − x/(3·Fγ·xT), reaching 2/3 at choked flow." },
  isentropic_efficiency: { term: "Isentropic efficiency ηs", def: "Work of reversible adiabatic (isentropic) compression divided by the actual work at the same pressure ratio. The actual discharge temperature is higher." },
  polytropic_efficiency: { term: "Polytropic efficiency ηp and exponent n", def: "Small-stage efficiency, linked to the exponent by (n−1)/n = (k−1)/(k·ηp). Nearly independent of pressure ratio; used for centrifugal machines.", unit: "%, —" },
  intercooling: { term: "Intercooling", def: "Cooling the gas between compression stages. Work is lowest with equal stage ratios and cooling back to the suction temperature." },
  discharge_temperature: { term: "Discharge temperature", def: "Gas temperature at a compressor stage outlet. Usually kept below about 150–180 °C for lubricant, seal and autoignition limits." },
  compression_ratio: { term: "Pressure ratio", def: "Absolute discharge pressure divided by absolute suction pressure. In N equal stages each stage ratio is the N-th root of the overall ratio." },
  hx_effectiveness: { term: "Effectiveness ε", def: "Actual heat duty divided by the maximum possible C_min·(T_h,i − T_c,i). Between 0 and 1; set by the flow arrangement, NTU and C_r.", ref: "Incropera, Ch. 11" },
  ntu: { term: "NTU (number of transfer units)", def: "Dimensionless thermal size UA/C_min of a heat exchanger. The larger it is, the closer the effectiveness gets to its maximum.", ref: "Incropera, Ch. 11" },
  capacity_ratio: { term: "Capacity ratio C_r", def: "Smaller heat capacity rate (ṁ·c_p) of the two streams divided by the larger. Zero when one side is at constant temperature (condensing, boiling)." },
  souders_brown_k: { term: "Souders–Brown K", def: "Empirical factor in the separator gas-velocity limit v_max = K·√((ρl−ρg)/ρg). Depends on mist eliminator, orientation and pressure." },
  holdup_time: { term: "Liquid hold-up time", def: "Time the collected liquid stays in the separator. Liquid volume = liquid flow × hold-up time sets vessel size; chosen for downstream control and surge margin." },
  probit: { term: "Probit value Pr", def: "The fraction affected by an exposure expressed in standard-deviation units of a normal distribution. Pr = 5 is 50 %, 2.67 is 1 % and 7.33 is 99 %.", ref: "Finney, Probit Analysis (1971)" },
  toxic_load: { term: "Toxic load Cⁿ·t", def: "Concentration C raised to the power n times exposure time t. Equal loads are taken to give equal effects; for a varying concentration add Σ Cᵢⁿ Δtᵢ." },
  lc_probit: { term: "LC50 · LC1", def: "Concentration at which 50 % (1 %) of those exposed for a stated time die. In a probit relation it is the concentration where Pr = 5 (2.67)." },
  release_grade: { term: "Grade of release", def: "Classification of a release by frequency and duration: continuous, primary (occasional in normal operation) or secondary (abnormal, brief); sets the zone." },
  release_characteristic: { term: "Release characteristic", def: "Release rate ÷ (gas density × k × LFL): the air flow needed to dilute the release to k·LFL, a measure of the ventilation dilution needs." },
  hypothetical_volume: { term: "Hypothetical volume V_z", def: "Volume where the mean gas concentration exceeds k·LFL (older IEC 60079-10 method). Below 0.1 m³ it is a candidate for negligible extent." },
  lfl_safety_factor: { term: "LFL safety factor k", def: "Factor applied to the LFL to lower the reference concentration, usually 0.5–1.0; smaller is more conservative." },
  ventilation_efficiency_factor: { term: "Ventilation efficiency factor f", def: "How much less effective the real ventilation is than ideal complete mixing: 1 is ideal, 5 is where air flow is impeded." },
  standing_loss: { term: "Standing (breathing) loss", def: "Vapor expelled as the vapor space expands and contracts with daily temperature and sunshine, even with a constant liquid level.", unit: "kg/yr" },
  working_loss: { term: "Working loss", def: "Vapor pushed out of the vapor space as the liquid level rises during filling. Proportional to throughput and turnovers.", unit: "kg/yr" },
  tank_total_loss: { term: "Total evaporative loss", def: "Standing plus working loss: the vapor released from the tank to air in one year.", unit: "kg/yr" },
  tank_throughput: { term: "Annual throughput", def: "Liquid volume filled into the tank per year. Gross throughput overstates working loss when filling and emptying happen at the same time.", unit: "m³/yr" },
  tank_turnovers: { term: "Turnovers N", def: "Sum of liquid level increases in a year divided by the difference between maximum and minimum liquid height. Above 36 the working loss factor K_N drops below 1.", unit: "1/yr" },
  vapor_expansion_factor: { term: "Vapor space expansion factor K_E", def: "Fraction of the vapor space expelled by the daily temperature and vapor pressure swing. Wider breather vent settings reduce it.", unit: "1/day" },
  vapor_saturation_factor: { term: "Vented vapor saturation factor K_S", def: "How close the vented vapor is to saturation (0–1). It falls as vapor pressure and vapor space height increase." },
  ambient_daily_range: { term: "Daily maximum and minimum temperature", def: "Annual averages of the daily maximum and minimum ambient temperatures at the site. Their difference drives tank breathing." },
  solar_insolation: { term: "Insolation", def: "Solar energy received by a horizontal surface per day (annual average). It heats the tank surface and the liquid." },
  solar_absorptance: { term: "Solar absorptance α", def: "Fraction of incident sunlight the tank surface absorbs (0–1). White and light colors have low values and lower losses.", ref: "US EPA AP-42 Table 7.1-6" },
  breather_vent: { term: "Breather (pressure/vacuum) vent", def: "Vent that opens only when the vapor space reaches its set pressure or vacuum. Wider settings reduce standing losses." },
  // ── Regulatory applicability checker (apl_*.jsx) ──
  apl_max_holding: { term: "Maximum holding", def: "Most that can be on site at any one moment, summed over all process and storage facilities. Tanks: design capacity × relative density.", ref: "NICS notice on prescribed quantities, Art. 2 and Annex 4" },
  apl_physical_state: { term: "Physical state", def: "State during handling: gas, liquid, solid or aqueous solution. It can change the quantity band or the Annex 13 entry (anhydrous vs solution)." },
  apl_facility_type: { term: "Facility type", def: "Manufacturing, general handling or storage facility (Dangerous Substances Act). Rows of one type count as one place; multiples are added.", ref: "Dangerous Substances Act Decree, Annexes 2–3" },
  apl_psm_quantity: { term: "PSM threshold quantity", def: "Quantity per hazardous substance that triggers a process safety report. It is compared with the most that can be made, handled or stored in one day.", ref: "OSH Act Enforcement Decree, Annex 13" },
  apl_psm_r: { term: "Summed ratio R", def: "Sum over substances of the maximum quantity C divided by the threshold T (C/T). At 1 or more the equipment counts as hazardous equipment.", ref: "OSH Act Enforcement Decree, Annex 13, note 7" },
  apl_cca_quantity: { term: "Lowest, lower and upper quantities", def: "Three quantities per hazardous chemical. The lower one triggers an accident prevention plan; the upper one makes a major handling facility.", ref: "NICS notice on prescribed quantities, Annexes 2–3" },
  apl_cca_tier: { term: "Tier 1 and tier 2 sites", def: "A site with any substance at its upper quantity is tier 1; with substances only at the lower quantity, tier 2. Inspection intervals and plan content differ.", ref: "Chemicals Control Act Enforcement Rule, Annex 4, note 2" },
  designated_quantity: { term: "Designated quantity", def: "Quantity set per dangerous-substance item. Storing or handling this much or more needs an installation permit; smaller amounts follow local ordinances.", ref: "Dangerous Substances Act Decree, Annex 1" },
  apl_multiple: { term: "Multiple of the designated quantity", def: "Amount ÷ designated quantity. Multiples of substances in one place are added; a sum of 1 or more counts as at or above the designated quantity.", ref: "Dangerous Substances Act, Art. 5(5)" },
  apl_dike_capacity: { term: "Dike capacity", def: "Effective volume the bund around tanks can hold. Outdoor tank storage needs at least 110 % of the largest tank (100 % for non-flammable liquids).", unit: "m³", ref: "Dangerous Substances Act Enforcement Rule, Annex 6 IX" },
  // ── Fire & explosion results (pool_fire · bleve · vce · probit_harm) ──
  pool_diameter: { term: "Pool diameter", def: "Diameter of the liquid pool. For a non-circular pool use the equivalent diameter √(4A/π); for a bunded pool, the bund floor size." },
  heat_of_combustion: { term: "Heat of combustion ΔHc", def: "Heat released when 1 kg of the substance burns completely. Fire and explosion models use the lower (net) heating value.", ref: "EPA RMP OCA Appendix C" },
  heat_of_vaporization: { term: "Heat of vaporisation ΔHv", def: "Heat needed to turn 1 kg of liquid into vapour at the same temperature. Pool-fire burning rates use the value at the boiling point." },
  burning_rate: { term: "Burning rate m″", def: "Fuel mass burned per square metre of pool surface per second. The Burgess correlation estimates it from the ratio of combustion and vaporisation heats.", ref: "Burgess et al. (1961)" },
  flame_height: { term: "Flame height", def: "Mean height of the pool-fire flame. Without wind, the Thomas correlation gives it from burning rate, pool diameter and air density.", ref: "Thomas (1963)" },
  fire_heat_release: { term: "Heat release rate", def: "Combustion heat released by the fire per second: burning rate × pool area × heat of combustion. Only part of it leaves as radiation." },
  surface_emissive_power: { term: "Surface emissive power E", def: "Radiant heat emitted per square metre of flame surface. For large pool fires it falls with diameter as smoke obscures the flame.", ref: "Shokri & Beyler (1989)" },
  view_factor: { term: "View factor F", def: "Fraction of the radiation leaving the flame that reaches the target surface. Set by flame size, shape and distance; between 0 and 1." },
  atm_transmissivity: { term: "Atmospheric transmissivity τ", def: "Fraction of thermal radiation not absorbed by water vapour and CO₂ on its way through air. Lower at high humidity and long distances." },
  radiative_fraction: { term: "Radiative fraction", def: "Fraction of the combustion heat emitted as thermal radiation: typically 0.15–0.35 for pool fires and 0.25–0.4 for fireballs." },
  point_source_model: { term: "Point-source model", def: "Simple model treating the fire as one point at the flame centre radiating equally in all directions. Valid only far from the flame." },
  solid_flame_model: { term: "Solid-flame model", def: "Treats the flame as a solid surface (cylinder, sphere): flux = emissive power × view factor × transmissivity. Better in the near field." },
  thermal_threshold: { term: "Heat-flux level distance", def: "Distance at which the heat flux falls to 4 (pain), 5 (endpoint), 12.5 (wood ignition) or 37.5 (equipment damage) kW/m²." },
  target_distance: { term: "Target distance", def: "Horizontal distance from the fire or explosion centre (pool centre, point below the fireball, cloud centre) to a person or building." },
  rmp_pff: { term: "Pool Fire Factor (PFF)", def: "Dimensionless factor listed per substance in the EPA RMP guidance. The 5 kW/m² distance = PFF × √(pool area), in consistent units.", ref: "EPA RMP OCA Eqs. 10-1, D-28" },
  rmp_endpoint: { term: "RMP endpoint distance", def: "Distance to the EPA RMP off-site endpoint (1 psi overpressure; 5 kW/m² for 40 s or the equivalent dose). Korea uses the same endpoints." },
  burst_vapor_pressure: { term: "Vapour pressure at rupture", def: "Absolute vapour pressure in the vessel just before it ruptures. Used in the fireball radiative fraction f = 0.27 P^0.32 (MPa).", ref: "CCPS (1994)" },
  fireball_diameter: { term: "Maximum fireball diameter", def: "Diameter of the BLEVE fireball at its largest, estimated as 5.8 M^(1/3) m for fuel mass M in kg.", ref: "Roberts (1982)" },
  fireball_duration: { term: "Fireball duration", def: "Burning time of the fireball: 0.45 M^(1/3) s below 30,000 kg and 2.6 M^(1/6) s above.", ref: "CCPS (1994)" },
  fireball_lift: { term: "Fireball centre height", def: "Height above ground of the fireball centre after lift-off, taken as 0.75 times the maximum diameter." },
  thermal_dose: { term: "Thermal dose", def: "Heat flux I to the 4/3 power times exposure time. 3.42 × 10⁶, equal to 5 kW/m² for 40 s, is the second-degree burn threshold.", ref: "Eisenberg et al. (1975)" },
  probit: { term: "Probit", def: "Probability of harm transformed to a normal-distribution scale: Y = a + b·ln(dose). Y = 5 means 50 % and 6.28 means 90 %.", ref: "Finney (1971)" },
  probit_percent: { term: "Probability of effect", def: "Share of exposed people or structures that suffer the effect (death, injury, damage), from the probit via the standard normal distribution." },
  overpressure_probit: { term: "Overpressure probit", def: "Probit for lung-haemorrhage death, eardrum rupture, structural damage or glass breakage from peak overpressure p [Pa].", ref: "Eisenberg et al. (1975)" },
  thermal_probit: { term: "Thermal probit", def: "Probit giving the probability of burn death and second- or first-degree burns from the thermal dose t·I^(4/3).", ref: "Eisenberg et al. (1975)" },
  exposure_time: { term: "Exposure time", def: "Time a person receives the heat flux: the fireball duration, or for long fires the time needed to escape (often 20–60 s)." },
  explosion_yield: { term: "Explosion yield η", def: "Fraction of the cloud's combustion energy that becomes blast. Typically 1–10 % in the TNT method; the EPA RMP worst case uses 10 %." },
  tnt_equivalent: { term: "TNT equivalent", def: "Mass of TNT giving the same overpressure: yield × fuel mass × heat of combustion ÷ TNT blast energy (about 4,686 kJ/kg)." },
  scaled_distance: { term: "Scaled distance z", def: "Distance divided by the cube root of the TNT mass (Hopkinson scaling). Equal z gives equal overpressure whatever the charge size." },
  side_on_overpressure: { term: "Peak side-on overpressure", def: "Peak pressure above atmospheric on a surface parallel to the passing blast wave. Windows break at about 1 psi (6.9 kPa)." },
  blast_threshold: { term: "Overpressure level distance", def: "Distance at which the overpressure falls to 1 psi (endpoint), 3.5 psi or 8 psi." },
  blast_energy: { term: "Blast energy E", def: "Combustion energy driving the blast in BST and Multi-Energy: fuel in congested regions × heat of combustion, doubled for clouds at ground." },
  sachs_scaled_distance: { term: "Sachs scaled distance", def: "Dimensionless distance R × (ambient pressure ÷ blast energy)^(1/3); the x-axis of the BST and TNO Multi-Energy blast curves." },
  flame_mach: { term: "Flame Mach number Mf", def: "Flame speed in the cloud divided by the speed of sound. BST takes it from a confinement-reactivity-congestion table; DDT is set to 5.2.", ref: "Pierorazio et al. (2005)" },
  confinement: { term: "Confinement", def: "Directions the flame can expand in: 3D open on all sides, 2D bounded above and below, 2.5D in between (weak panels, dense pipe racks)." },
  fuel_reactivity: { term: "Fuel reactivity", def: "Class by laminar burning velocity: methane and CO low; hydrogen, acetylene, ethylene and ethylene oxide high; most others medium.", ref: "Zeeuwen & Wiekema (1978)" },
  congestion: { term: "Obstacle congestion", def: "Density of pipes and equipment in the flame path: low below 10 % area blockage, high at 40 % or more with closely spaced layers." },
  congested_mass: { term: "Fraction in congested regions", def: "Share of the cloud's fuel inside congested regions that takes part in the explosion. Fuel in open areas produces little blast." },
  ground_reflection: { term: "Ground reflection", def: "A blast from a cloud at ground level reflects off the ground and acts like a free-air blast of twice the energy. Use 1 for an elevated cloud." },

  // ── Real-fluid properties & refrigeration cycle (calc_fluid_props.jsx) ──
  refrigerant: { term: "Refrigerant (R134a, R32, R410A …)", def: "Working fluid that moves heat by evaporating and condensing, named by ASHRAE 34 R-numbers; natural ones include ammonia R717, CO₂ R744, propane R290." },
  ph_diagram: { term: "p-h diagram (Mollier chart)", def: "Chart of specific enthalpy h against log pressure P. The saturation dome encloses the two-phase region; refrigeration-cycle steps appear as lines on it." },
  fluid_state_pair: { term: "Two given state variables", def: "Two independent intensive properties fix the state of a pure substance (state postulate). In the two-phase region T and P are tied, so give the quality x.", ref: "Smith, Van Ness & Abbott, Ch. 2" },
  fluid_quality: { term: "Quality x", def: "Mass fraction of vapour in 1 kg of a two-phase mixture: 0 is saturated liquid, 1 is saturated vapour. Not defined in single-phase states." },
  fluid_phase: { term: "Phase", def: "Compressed (subcooled) liquid, saturated liquid, two-phase, saturated vapour, superheated vapour, or supercritical (above both Tc and pc)." },
  evaporating_temperature: { term: "Evaporating temperature and pressure", def: "Saturation temperature at which the refrigerant boils in the evaporator, and its pressure. Usually 5–10 K below the space being cooled." },
  condensing_temperature: { term: "Condensing temperature and pressure", def: "Saturation temperature at which the refrigerant condenses, and its pressure. Usually 5–15 K above the cooling water or ambient air." },
  superheat: { term: "Superheat", def: "How far the compressor suction temperature is above the saturation (dew) temperature at evaporating pressure. It keeps liquid out of the compressor." },
  subcooling: { term: "Subcooling", def: "How far the condenser-outlet liquid is below the saturation (bubble) temperature at condensing pressure. More subcooling raises the refrigerating effect." },
  refrigerating_effect: { term: "Refrigerating effect and capacity", def: "Heat absorbed per kg of refrigerant in the evaporator (h1 − h4) is the refrigerating effect; per unit time (kW) it is the capacity. 1 US ton = 3.517 kW." },
  cycle_cop: { term: "Coefficient of performance COP (cooling)", def: "Refrigeration heat divided by compressor work. The Carnot COP = T_e/(T_c − T_e) at the same temperatures is the theoretical limit.", ref: "Çengel & Boles, Ch. 11" },
  compressor_work: { term: "Compressor work and power", def: "Work to compress 1 kg of refrigerant from evaporating to condensing pressure (h2 − h1); times the mass flow it is the compressor power." },
  pressure_ratio: { term: "Pressure ratio", def: "Condensing (discharge) over evaporating (suction) pressure, both absolute. Higher ratios raise the discharge temperature and cut volumetric efficiency." },
  ashrae_safety_group: { term: "ASHRAE 34 safety group", def: "Class combining toxicity (A lower, B higher) and flammability (1 none, 2L mild, 2 and 3 higher). E.g. R134a A1, R32 A2L, ammonia B2L, propane A3." },

  // ── Binary vapour–liquid equilibrium (calc_vle_binary.jsx) ──
  vle_diagram: { term: "VLE diagram (Txy, Pxy, x–y)", def: "Equilibrium liquid (x) and vapour (y) compositions against temperature (isobaric Txy) or pressure (isothermal Pxy). The x–y curve underlies McCabe–Thiele." },
  vle_component: { term: "VLE component", def: "By convention component 1 is the more volatile one. Presets combine UNIFAC groups with Antoine constants fitted to CoolProp vapour pressures." },
  activity_model: { term: "Activity-coefficient model γ", def: "Gives γ, the liquid's departure from ideal solution. γ > 1 is positive deviation (minimum-boiling azeotropes possible), γ < 1 negative; Raoult has γ = 1.", ref: "Smith, Van Ness & Abbott, Ch. 12" },
  margules_vanlaar: { term: "Margules and van Laar parameters", def: "Constants of binary excess Gibbs energy equations: A₁₂ = ln γ₁∞ and A₂₁ = ln γ₂∞ (logs of the infinite-dilution activity coefficients)." },
  wilson_nrtl: { term: "Wilson and NRTL parameters", def: "Energy parameters (a_ij, b_ij), molar volumes and non-randomness α of local-composition models, from the literature (DECHEMA etc.) or fitted to VLE data." },
  unifac_group: { term: "UNIFAC subgroups", def: "Small structural groups such as CH3, CH2, OH and ACH. Group size (R), area (Q) and pair interactions (a_mn) predict γ." },
  vle_mole_fraction: { term: "Mole fractions x₁, y₁", def: "x₁ is the mole fraction of component 1 in the liquid, y₁ in the vapour. For two components x₂ = 1 − x₁." },
  bubble_dew_point: { term: "Bubble and dew points", def: "The bubble point is where a liquid forms its first vapour bubble; the dew point is where a vapour forms its first drop. Between them is two-phase." },
  vle_relative_volatility: { term: "Relative volatility α₁₂", def: "(y₁/x₁)/(y₂/x₂) = γ₁P₁ˢᵃᵗ/(γ₂P₂ˢᵃᵗ). The further from 1, the easier the distillation; α₁₂ = 1 at an azeotrope." },
  azeotrope_point: { term: "Azeotrope", def: "Composition where liquid and vapour are equal (y = x), so simple distillation stops there. Ethanol–water: minimum-boiling, about 78.2 °C and 89 mol% at 1 atm." },
  group_contribution: { term: "Group contribution", def: "Estimates a property by splitting the molecule into groups (-CH3, >C=O, -OH …) and adding a value per group. For first estimates without measured data.", ref: "Joback & Reid (1987) Chem. Eng. Commun. 57, 233" },
  smiles: { term: "SMILES", def: "A one-line text notation for a molecular structure. Example: CC(=O)C is acetone, c1ccccc1 is benzene (lower case = aromatic ring)." },
  formation_enthalpy: { term: "Enthalpy of formation ΔHf°", def: "Enthalpy change when 1 mol of the substance is formed from its elements in their standard states at 298.15 K and 1 bar. Negative means heat is released.", unit: "kJ/mol" },
  formation_gibbs: { term: "Gibbs energy of formation ΔGf°", def: "Gibbs energy change when 1 mol of the substance is formed from its elements at 298.15 K and 1 bar. Used for reaction equilibrium constants.", unit: "kJ/mol" },
  melting_point: { term: "Melting point", def: "Temperature at which the solid turns into liquid (1 atm).", unit: "K" },
  // ── Off-site screening and release rate (calc_offsite, calc_release) ──
  offsite_assessment: { term: "Off-site impact assessment", def: "Assessment of how far a chemical accident could affect people and the environment outside the site. In Korea it is computed with the NICS tool KORA.", ref: "Chemicals Control Act, Art. 23 (Korea)" },
  endpoint: { term: "Endpoint", def: "The concentration, overpressure or radiant heat that defines the impact distance: ERPG-2 etc. for toxics, 1 psi for explosions, 5 kW/m² (40 s) for fires.", ref: "40 CFR 68.22; NICS technical guideline" },
  endpoint_erpg: { term: "ERPG-2", def: "Maximum airborne concentration that nearly everyone could breathe for 1 h without irreversible health effects or losing the ability to escape. Set by AIHA.", ref: "AIHA ERPG (values via DOE PAC)" },
  endpoint_aegl: { term: "AEGL-2", def: "Level at which the public, exposed for 10 min to 8 h, could suffer irreversible or lasting effects or impaired escape. Published by US EPA.", ref: "U.S. EPA AEGL" },
  endpoint_pac: { term: "PAC-2", def: "US Department of Energy protective action criterion: for each chemical one 60-min value taken from AEGL-2, else ERPG-2, else TEEL-2.", ref: "DOE PAC Rev. 29" },
  rmp: { term: "RMP (Risk Management Program)", def: "US Clean Air Act §112(r) accident prevention program. Sites above threshold quantities report off-site distances for worst-case and alternative scenarios.", ref: "40 CFR Part 68" },
  worst_case: { term: "Worst-case scenario", def: "Release of the whole contents of the largest vessel or pipe; a gas leaves in 10 min, with adverse weather such as stability F and 1.5 m/s wind.", ref: "40 CFR 68.25" },
  alternative_case: { term: "Alternative scenario", def: "A more likely release than the worst case (a hole, a broken pipe); average weather (D, 3 m/s) and active or passive mitigation may be credited.", ref: "40 CFR 68.28" },
  release_rate: { term: "Release rate", def: "Mass of material leaving to the air per unit time. It is the input to dispersion and endpoint-distance calculations." },
  release_duration: { term: "Release duration", def: "How long the release lasts. For a pool it is quantity ÷ evaporation rate; RMP uses it to choose the 10-min or 60-min table." },
  quantity_released: { term: "Quantity released", def: "Total mass released in one accident. In the worst case it is the whole contents of the largest vessel." },
  hole_size: { term: "Hole size", def: "Diameter of the leak (assumed round). Alternative scenarios often use the size of a sheared valve or pipe." },
  topography: { term: "Topography (rural/urban)", def: "Selects the dispersion table: rural for open areas with few obstructions, urban where buildings or equipment are dense, even far from a city." },
  passive_mitigation: { term: "Passive mitigation", def: "Equipment that limits a release without people or power: a dike limits the pool area, a building limits what escapes outside." },
  dike_area: { term: "Diked area", def: "Floor area enclosed by a dike. If it is smaller than a 1 cm deep pool, evaporation is limited to this area." },
  impact_distance: { term: "Impact distance (endpoint distance)", def: "Distance from the source to where the endpoint concentration, overpressure or radiant heat is reached; people inside that circle are in the impact range." },
  pool_area: { term: "Pool area", def: "Area covered by the spilled liquid. The RMP guidance assumes a 1 cm deep pool, limited to the diked area if there is a dike." },
  drain_time: { term: "Tank draining time", def: "Time for the liquid above the hole to run out. The release rate falls as the level drops." },
};

const TERM_HINT_LABELS = langPick(TERM_HINT_LABELS_KO, TERM_HINT_LABELS_EN);
const TERM_GLOSSARY = langPick(TERM_GLOSSARY_KO, TERM_GLOSSARY_EN);

Object.assign(window, { TERM_GLOSSARY_EN, TERM_HINT_LABELS_EN, TERM_GLOSSARY, TERM_HINT_LABELS });
